use vstd::prelude::*;

verus! {
    /// A vector that has been “expanded” into either a row or a column.
    pub enum ExpandedVector<T> {
        RowVector(Vec<T>),
        ColumnVector(Vec<T>),
    }

    /// Expand a 1–D Vec<T> into a RowVector or ColumnVector,
    /// according to `axis == 0` or `axis == 1`.
    fn expand_dims<T>(a: Vec<T>, axis: usize) -> (res: ExpandedVector<T>)
        requires
            // we only allow axis 0 or 1
            axis <= 1,
        ensures
            // if axis==0 then we get a RowVector(a),
            // otherwise (axis==1) we get a ColumnVector(a)
            match res {
                ExpandedVector::RowVector(inner)   => axis == 0 && inner == a,
                ExpandedVector::ColumnVector(inner) => axis == 1 && inner == a,
            }
    {
        // catch misuse at runtime in debug builds
        assert!(axis <= 1, "axis must be 0 (row) or 1 (column)");

        if axis == 0 {
            ExpandedVector::RowVector(a)
        } else {
            ExpandedVector::ColumnVector(a)
        }
    }
}

